package dental.flow.api.adapters.rest.out.persistence.entity;
import jakarta.persistence.*; import java.time.LocalTime;
@Entity @Table(name="escala_equipe") public class TeamScheduleEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_escala_equipe") private Long id; @Column(name="id_mapa_diario",nullable=false) private Long dailyMapId; @Column(name="id_usuario") private Long userId; @Column(name="nome_funcionario") private String employeeName; @Column(name="funcao",nullable=false) private String role; @Column(name="hora_inicio") private LocalTime startTime; @Column(name="hora_saida_almoco") private LocalTime lunchOutTime; @Column(name="hora_volta_almoco") private LocalTime lunchReturnTime; @Column(name="hora_final") private LocalTime endTime; public TeamScheduleEntity(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getDailyMapId(){return dailyMapId;} public void setDailyMapId(Long v){dailyMapId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getEmployeeName(){return employeeName;} public void setEmployeeName(String v){employeeName=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public LocalTime getStartTime(){return startTime;} public void setStartTime(LocalTime v){startTime=v;} public LocalTime getLunchOutTime(){return lunchOutTime;} public void setLunchOutTime(LocalTime v){lunchOutTime=v;} public LocalTime getLunchReturnTime(){return lunchReturnTime;} public void setLunchReturnTime(LocalTime v){lunchReturnTime=v;} public LocalTime getEndTime(){return endTime;} public void setEndTime(LocalTime v){endTime=v;} }
